// Reposed to the atlas frame. Coordinates remain educational approximations.
const packed = {"positions":"","indices":"","skinIndexCount":80268,"vertexCount":13524};
function decode(text,signed){const raw=atob(text),view=new DataView(new ArrayBuffer(raw.length));for(let i=0;i<raw.length;i++)view.setUint8(i,raw.charCodeAt(i));const out=[];for(let i=0;i<raw.length;i+=2)out.push(signed?view.getInt16(i,true)/1000:view.getUint16(i,true));return out;}
export function createHuman(){
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(decode(packed.positions,true),3));geometry.setIndex(decode(packed.indices,false));geometry.computeVertexNormals();geometry.computeBoundingSphere();
 geometry.addGroup(0,packed.skinIndexCount,0);geometry.addGroup(packed.skinIndexCount,geometry.index.count-packed.skinIndexCount,1);
 const skin=new T.MeshPhysicalMaterial({color:0xc89373,roughness:.67,metalness:0,clearcoat:.08,clearcoatRoughness:.7});
 const eye=new T.MeshPhysicalMaterial({color:0xebe0d5,roughness:.28,metalness:0});
 return new T.Mesh(geometry,[skin,eye]);
}
export function nearestSurface(mesh,position){
 const attr=mesh.geometry.attributes.position,normals=mesh.geometry.attributes.normal;let best=Infinity,index=0;
 for(let i=0;i<attr.count;i++){const dx=attr.getX(i)-position.x,dy=attr.getY(i)-position.y,dz=attr.getZ(i)-position.z;const distance=dx*dx+dy*dy+dz*dz;if(distance<best){best=distance;index=i;}}
 return {point:new T.Vector3().fromBufferAttribute(attr,index),normal:new T.Vector3().fromBufferAttribute(normals,index).normalize()};
}
